CREATE SCHEMA IF NOT EXISTS crm;
SET search_path TO crm,public;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, ai_mode text NOT NULL DEFAULT 'off' CHECK(ai_mode IN ('off','fixture','openai')));
CREATE TABLE memberships(workspace_id uuid REFERENCES workspaces, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE invitations(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member','viewer')), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz, PRIMARY KEY(workspace_id,id));
CREATE TABLE objects(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), name text NOT NULL, plural text NOT NULL, key text NOT NULL, icon text NOT NULL DEFAULT 'layers', revision int NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,key));
CREATE TABLE fields(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('text','longtext','decimal','number','date','timestamp','boolean','email','phone','url','select','multi')), required boolean NOT NULL DEFAULT false, options jsonb NOT NULL DEFAULT '[]', position int NOT NULL DEFAULT 0, archived boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects);
CREATE TABLE object_revisions(workspace_id uuid, object_id uuid, revision int, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,object_id,revision), FOREIGN KEY(workspace_id,object_id) REFERENCES objects);
CREATE TABLE pipelines(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, name text NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,object_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects);
CREATE TABLE stages(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), pipeline_id uuid NOT NULL, name text NOT NULL, color text NOT NULL DEFAULT 'blue', position int NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,pipeline_id,id), FOREIGN KEY(workspace_id,pipeline_id) REFERENCES pipelines);
CREATE TABLE records(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, title text NOT NULL, owner_id uuid, pipeline_id uuid, stage_id uuid, fields jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(fields)='object'), version int NOT NULL DEFAULT 1, schema_revision int NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,object_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects, FOREIGN KEY(workspace_id,object_id,schema_revision) REFERENCES object_revisions, FOREIGN KEY(workspace_id,owner_id) REFERENCES memberships, FOREIGN KEY(workspace_id,object_id,pipeline_id) REFERENCES pipelines(workspace_id,object_id,id), FOREIGN KEY(workspace_id,pipeline_id,stage_id) REFERENCES stages(workspace_id,pipeline_id,id), CHECK((stage_id IS NULL)=(pipeline_id IS NULL)));
CREATE INDEX records_active_by_object ON records(workspace_id,object_id,updated_at DESC,id) WHERE archived_at IS NULL;
CREATE INDEX records_active_by_stage ON records(workspace_id,stage_id,id) WHERE archived_at IS NULL;
CREATE INDEX records_search ON records USING gin(to_tsvector('simple',title)) WHERE archived_at IS NULL;
CREATE TABLE relations(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), source_object uuid NOT NULL, target_object uuid NOT NULL, label text NOT NULL, inverse text NOT NULL, cardinality text NOT NULL CHECK(cardinality IN ('one-one','one-many','many-many')), PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,id,source_object,target_object,cardinality), FOREIGN KEY(workspace_id,source_object) REFERENCES objects, FOREIGN KEY(workspace_id,target_object) REFERENCES objects);
CREATE TABLE edges(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), relation_id uuid NOT NULL, source_object uuid NOT NULL, target_object uuid NOT NULL, source_id uuid NOT NULL, target_id uuid NOT NULL, cardinality text NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,relation_id,source_id,target_id), FOREIGN KEY(workspace_id,relation_id,source_object,target_object,cardinality) REFERENCES relations(workspace_id,id,source_object,target_object,cardinality), FOREIGN KEY(workspace_id,source_object,source_id) REFERENCES records(workspace_id,object_id,id), FOREIGN KEY(workspace_id,target_object,target_id) REFERENCES records(workspace_id,object_id,id), CHECK(source_id<>target_id));
CREATE UNIQUE INDEX edge_one_source ON edges(workspace_id,relation_id,source_id) WHERE cardinality='one-one';
CREATE UNIQUE INDEX edge_one_target ON edges(workspace_id,relation_id,target_id) WHERE cardinality IN ('one-one','one-many');
CREATE INDEX edge_target_lookup ON edges(workspace_id,target_id);
CREATE TABLE activities(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), record_id uuid NOT NULL, actor_id uuid, kind text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,record_id) REFERENCES records, FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
CREATE INDEX activity_by_record ON activities(workspace_id,record_id,created_at DESC);
CREATE TABLE tasks(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), record_id uuid, assignee_id uuid, title text NOT NULL, due_at date, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,record_id) REFERENCES records, FOREIGN KEY(workspace_id,assignee_id) REFERENCES memberships);
CREATE INDEX tasks_due ON tasks(workspace_id,status,due_at);
CREATE TABLE views(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, creator_id uuid NOT NULL, name text NOT NULL, query jsonb NOT NULL, shared boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects, FOREIGN KEY(workspace_id,creator_id) REFERENCES memberships);
CREATE TABLE templates(workspace_id uuid REFERENCES workspaces, key text NOT NULL, version int NOT NULL, PRIMARY KEY(workspace_id,key,version));
CREATE TABLE imports(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, actor_id uuid NOT NULL, schema_revision int NOT NULL, rows jsonb NOT NULL, errors jsonb NOT NULL DEFAULT '[]', committed_at timestamptz, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects, FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
CREATE TABLE workflows(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), object_id uuid NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, trigger text NOT NULL CHECK(trigger IN ('stage','schedule')), settings jsonb NOT NULL, actor_id uuid NOT NULL, next_run timestamptz, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects, FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
CREATE TABLE workflow_runs(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), workflow_id uuid NOT NULL, event_id uuid NOT NULL, record_id uuid NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,workflow_id,event_id,record_id), FOREIGN KEY(workspace_id,workflow_id) REFERENCES workflows, FOREIGN KEY(workspace_id,record_id) REFERENCES records);
CREATE TABLE notifications(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), user_id uuid NOT NULL, message text NOT NULL, seen boolean NOT NULL DEFAULT false, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships);
CREATE TABLE outbox(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), available_at timestamptz NOT NULL DEFAULT now(), attempts int NOT NULL DEFAULT 0, outcome text, PRIMARY KEY(workspace_id,id));
CREATE INDEX outbox_ready ON outbox(workspace_id,available_at) WHERE outcome IS NULL;
CREATE TABLE ai_threads(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
CREATE TABLE ai_messages(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), thread_id uuid NOT NULL, question text NOT NULL, answer text NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,thread_id) REFERENCES ai_threads ON DELETE CASCADE);
CREATE TABLE ai_actions(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, thread_id uuid NOT NULL, record_id uuid NOT NULL, record_version int NOT NULL, payload jsonb NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes', outcome text, task_id uuid, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships, FOREIGN KEY(workspace_id,thread_id) REFERENCES ai_threads ON DELETE CASCADE, FOREIGN KEY(workspace_id,record_id) REFERENCES records, FOREIGN KEY(workspace_id,task_id) REFERENCES tasks);
CREATE TABLE ai_usage(workspace_id uuid, id uuid DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, mode text NOT NULL, used_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
CREATE TABLE audit(workspace_id uuid REFERENCES workspaces, id uuid DEFAULT gen_random_uuid(), actor_id uuid, event text NOT NULL, target_id uuid, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,actor_id) REFERENCES memberships);
GRANT USAGE ON SCHEMA crm TO crm_app;
GRANT SELECT ON users TO crm_app;
GRANT SELECT,INSERT,DELETE ON sessions TO crm_app;
GRANT SELECT ON workspaces,memberships TO crm_app;
GRANT UPDATE(ai_mode) ON workspaces TO crm_app;
CREATE FUNCTION tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('crm.workspace',true),'')::uuid $$;
CREATE FUNCTION actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('crm.actor',true),'')::uuid $$;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY membership_lookup ON memberships USING (user_id=actor() OR workspace_id=tenant()) WITH CHECK(workspace_id=tenant());
GRANT INSERT,UPDATE ON memberships TO crm_app;
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
ALTER TABLE workspaces FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_lookup ON workspaces USING (id=tenant() OR EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=workspaces.id AND m.user_id=actor() AND m.active)) WITH CHECK(id=tenant());
DO $$
DECLARE t text;
BEGIN
 FOREACH t IN ARRAY ARRAY['invitations','objects','fields','object_revisions','pipelines','stages','records','relations','edges','activities','tasks','views','templates','imports','workflows','workflow_runs','notifications','outbox','ai_threads','ai_messages','ai_actions','ai_usage','audit']
 LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY workspace_scope ON %I USING (workspace_id=tenant()) WITH CHECK (workspace_id=tenant())',t);
  EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO crm_app',t);
 END LOOP;
END $$;
REVOKE UPDATE,DELETE ON audit,object_revisions FROM crm_app;
